-- PostgreSQL DDL matching backend/app/models/models.py.
-- CREATE statements support fresh installs; additive ALTERs preserve old rows.
-- IDs are VARCHAR UUIDs generated by the application; money uses NUMERIC.

DO $$ BEGIN
    CREATE TYPE statement_status AS ENUM (
        'INITIAL', 'TRANSCRIBED', 'EXTRACTED', 'AWAITING_INFORMATION',
        'READY_FOR_CONFIRMATION', 'CONFIRMED', 'REJECTED'
    );
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

DO $$ BEGIN
    CREATE TYPE payment_type AS ENUM ('cash', 'upi', 'bank', 'advance', 'other');
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

CREATE TABLE IF NOT EXISTS workers (
    id VARCHAR(36) PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    phone VARCHAR(15) NOT NULL UNIQUE,
    preferred_language VARCHAR(10) NOT NULL DEFAULT 'hi',
    pin_hash VARCHAR(255) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_workers_phone ON workers (phone);

CREATE TABLE IF NOT EXISTS employers (
    id VARCHAR(36) PRIMARY KEY,
    worker_id VARCHAR(36) NOT NULL REFERENCES workers(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    contact_details VARCHAR(500),
    created_at TIMESTAMPTZ NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_employers_worker_id ON employers (worker_id);

CREATE TABLE IF NOT EXISTS voice_statements (
    id VARCHAR(36) PRIMARY KEY,
    worker_id VARCHAR(36) NOT NULL REFERENCES workers(id) ON DELETE CASCADE,
    transcript TEXT,
    language VARCHAR(10) NOT NULL DEFAULT 'hi',
    extracted_data JSON,
    status statement_status NOT NULL DEFAULT 'INITIAL',
    conversation_history JSON,
    created_at TIMESTAMPTZ NOT NULL,
    confirmed_at TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS ix_voice_statements_worker_id ON voice_statements (worker_id);

CREATE TABLE IF NOT EXISTS work_entries (
    id VARCHAR(36) PRIMARY KEY,
    worker_id VARCHAR(36) NOT NULL REFERENCES workers(id) ON DELETE CASCADE,
    employer_id VARCHAR(36) REFERENCES employers(id) ON DELETE SET NULL,
    work_date TIMESTAMPTZ NOT NULL,
    days_worked NUMERIC(15, 2) NOT NULL,
    hours_worked NUMERIC(15, 2),
    wage_basis VARCHAR(10) NOT NULL DEFAULT 'daily',
    hourly_rate NUMERIC(15, 2),
    overtime_hours NUMERIC(15, 2) NOT NULL DEFAULT 0,
    overtime_multiplier NUMERIC(4, 2) NOT NULL DEFAULT 1.5,
    daily_wage NUMERIC(15, 2) NOT NULL,
    total_earned NUMERIC(15, 2) NOT NULL,
    description TEXT,
    source_statement_id VARCHAR(36) REFERENCES voice_statements(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL
);
ALTER TABLE work_entries ADD COLUMN IF NOT EXISTS wage_basis VARCHAR(10) NOT NULL DEFAULT 'daily';
ALTER TABLE work_entries ADD COLUMN IF NOT EXISTS hourly_rate NUMERIC(15, 2);
ALTER TABLE work_entries ADD COLUMN IF NOT EXISTS overtime_hours NUMERIC(15, 2) NOT NULL DEFAULT 0;
ALTER TABLE work_entries ADD COLUMN IF NOT EXISTS overtime_multiplier NUMERIC(4, 2) NOT NULL DEFAULT 1.5;
DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ck_work_entries_wage_basis_allowed') THEN
        ALTER TABLE work_entries ADD CONSTRAINT ck_work_entries_wage_basis_allowed CHECK (wage_basis IN ('daily', 'hourly'));
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ck_work_entries_hourly_rate_positive') THEN
        ALTER TABLE work_entries ADD CONSTRAINT ck_work_entries_hourly_rate_positive CHECK (hourly_rate IS NULL OR hourly_rate > 0);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ck_work_entries_overtime_non_negative') THEN
        ALTER TABLE work_entries ADD CONSTRAINT ck_work_entries_overtime_non_negative CHECK (overtime_hours >= 0);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ck_work_entries_overtime_multiplier') THEN
        ALTER TABLE work_entries ADD CONSTRAINT ck_work_entries_overtime_multiplier CHECK (overtime_multiplier >= 1 AND overtime_multiplier <= 3);
    END IF;
END $$;
CREATE INDEX IF NOT EXISTS ix_work_entries_worker_id ON work_entries (worker_id);
CREATE INDEX IF NOT EXISTS ix_work_entries_employer_id ON work_entries (employer_id);

CREATE TABLE IF NOT EXISTS payments (
    id VARCHAR(36) PRIMARY KEY,
    worker_id VARCHAR(36) NOT NULL REFERENCES workers(id) ON DELETE CASCADE,
    employer_id VARCHAR(36) REFERENCES employers(id) ON DELETE SET NULL,
    amount NUMERIC(15, 2) NOT NULL,
    payment_date TIMESTAMPTZ NOT NULL,
    payment_type payment_type NOT NULL,
    notes TEXT,
    source_statement_id VARCHAR(36) REFERENCES voice_statements(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_payments_worker_id ON payments (worker_id);
CREATE INDEX IF NOT EXISTS ix_payments_employer_id ON payments (employer_id);

CREATE TABLE IF NOT EXISTS payment_allocations (
    id VARCHAR(36) PRIMARY KEY,
    worker_id VARCHAR(36) NOT NULL REFERENCES workers(id) ON DELETE CASCADE,
    payment_id VARCHAR(36) NOT NULL REFERENCES payments(id) ON DELETE CASCADE,
    work_entry_id VARCHAR(36) NOT NULL REFERENCES work_entries(id) ON DELETE CASCADE,
    amount NUMERIC(15, 2) NOT NULL CHECK (amount > 0),
    created_at TIMESTAMPTZ NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_payment_allocations_worker_id ON payment_allocations (worker_id);
CREATE INDEX IF NOT EXISTS ix_payment_allocations_payment_id ON payment_allocations (payment_id);
CREATE INDEX IF NOT EXISTS ix_payment_allocations_work_entry_id ON payment_allocations (work_entry_id);

CREATE TABLE IF NOT EXISTS evidence_files (
    id VARCHAR(36) PRIMARY KEY,
    worker_id VARCHAR(36) NOT NULL REFERENCES workers(id) ON DELETE CASCADE,
    statement_id VARCHAR(36) REFERENCES voice_statements(id) ON DELETE SET NULL,
    file_reference VARCHAR(500) NOT NULL,
    document_type VARCHAR(100),
    created_at TIMESTAMPTZ NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_evidence_files_worker_id ON evidence_files (worker_id);
CREATE INDEX IF NOT EXISTS ix_evidence_files_statement_id ON evidence_files (statement_id);

-- Additive audit history. This table can also be applied to an existing schema.
-- Existing worker, employer, ledger, and statement rows are never copied or reset.
CREATE TABLE IF NOT EXISTS audit_events (
    id VARCHAR(36) PRIMARY KEY,
    worker_id VARCHAR(36) NOT NULL REFERENCES workers(id) ON DELETE CASCADE,
    event_type VARCHAR(80) NOT NULL,
    entity_type VARCHAR(80) NOT NULL,
    entity_id VARCHAR(36) NOT NULL,
    source_statement_id VARCHAR(36) REFERENCES voice_statements(id) ON DELETE SET NULL,
    details JSON NOT NULL DEFAULT '{}'::json,
    created_at TIMESTAMPTZ NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_audit_events_worker_id ON audit_events (worker_id);
CREATE INDEX IF NOT EXISTS ix_audit_events_source_statement_id ON audit_events (source_statement_id);
CREATE INDEX IF NOT EXISTS ix_audit_events_worker_created ON audit_events (worker_id, created_at);
CREATE INDEX IF NOT EXISTS ix_audit_events_entity ON audit_events (entity_type, entity_id);
